/* Bo tròn 8px giao diện Teeinblue */
.teeinblue-enabled button.tee-btn,
.teeinblue-enabled div.tee-radio,
.teeinblue-enabled .tee-field__select,
.teeinblue-enabled .tee-form-input,
.teeinblue-enabled .tee-clipart,
.teeinblue-enabled .tee-photo-placeholder,
.teeinblue-enabled .tee-photo-action .tee-btn,
.teeinblue-enabled .tee__paragraph,
.teeinblue-enabled .tee-timepicker__input {
  border-radius: 8px !important;
}

.teeinblue-enabled .tee-quantity-minus {
  border-top-left-radius: 8px;
  border-bottom-left-radius: 8px;
}

.teeinblue-enabled .tee-quantity-plus {
  border-top-right-radius: 8px;
  border-bottom-right-radius: 8px;
}

.tee-slider .tee-slide,
.tee-mockup-item .tee-mockup-image,
.tee-mockup-item .tee-printarea-wrapper--image > img {
  border-radius: 8px;
}

/* Hỗ trợ hiển thị RTL cho Teeinblue */
@media only screen and (min-width: 992px) {
  .tee-dialog-image-cropper.vm--modal {
    left: -50% !important;
    transform: translateX(50%) !important;
  }
}

@media only screen and (max-width: 990px) {
  .teeinblue-enabled .product {
    overflow: hidden;
  }
}

/* Image Cropper Classic Style */
.tee-dialog-image-cropper .cropper-view-box {
  outline: 2px solid #fff !important;
  outline-color: rgba(255, 255, 255, 0.75) !important;
}

.tee-dialog-image-cropper .cropper-line {
  background-color: transparent !important;
}

.tee-dialog-image-cropper .cropper-point {
  width: 10px !important;
  height: 10px !important;
  background-color: #39f !important;
}

/* Fix preview popup overlap */
.vm--container.tee-preview-popup,
.vm--container.tee-dialog-preview {
  z-index: 99999999 !important;
}

.teeinblue-enabled .shopify-section-header-sticky {
  z-index: 100 !important;
}

/* Fix scrollable in iOS browsers */
html.tee-overflow-hidden,
body.tee-overflow-hidden {
  position: static !important;
  overflow: auto !important;
  -webkit-overflow-scrolling: touch;
}

/* Loading shimmer placeholder */
#tib-loading-placeholder {
  width: 100%;
  padding: 24px;
  background: #f7f7f7;
  border-radius: 8px;
  margin-bottom: 16px;
  text-align: center;
  color: #666;
  font-weight: 500;
  animation: tibPulse 1.5s infinite;
}

@keyframes tibPulse {
  0% { opacity: 0.6; }
  50% { opacity: 1; }
  100% { opacity: 0.6; }
}
